mapper.select:
SELECT record_id, amount, balance, reason, create_time
FROM user_point_records
WHERE user_id = #{userId}
ORDER BY record_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT check_in_date, points, consecutive_days
FROM user_check_ins
WHERE user_id = #{userId} AND check_in_date = #{date}

mapper.update:
UPDATE user_stats
SET moe_point = moe_point + #{amount}
WHERE user_id = #{userId} AND moe_point + #{amount} >= 0
